        var frame=ui.col();var sc=new ScrollView(this);sc.addView(content);frame.addView(sc,new LinearLayout.LayoutParams(-1,0,1));var dialog=ui.sheet("Модель и усилие",frame);modelDialog=dialog;ui.compact(dialog,460);
