    private void renderQuotaSummary(){
        if(quotaSummary==null)return;
        var text=new SpannableStringBuilder();var descriptions=new ArrayList<String>();var buckets=array(object(snapshot,"quota"),"buckets");
        for(int i=0;i<buckets.length();i++){
            var bucket=buckets.optJSONObject(i);if(bucket==null)continue;var windows=array(bucket,"windows");Integer left=null;
            for(int j=0;j<windows.length();j++){var window=windows.optJSONObject(j);if(window!=null&&window.opt("remainingPercent") instanceof Number n){int value=Math.max(0,Math.min(100,n.intValue()));left=left==null?value:Math.min(left,value);}}
            if(text.length()>0)text.append("/");int start=text.length();text.append(left==null?"—":left+"%");
            text.setSpan(new android.text.style.ForegroundColorSpan(left==null?Ui.MUTED:left<=5?Ui.RED:left<=20?Ui.AMBER:Ui.GREEN),start,text.length(),Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);
            descriptions.add(bucket.optString("label")+": "+(left==null?"нет данных":left+"%"));
        }
        if(text.length()==0)text.append("—");
        if(!TextUtils.equals(quotaSummary.getText(),text))quotaSummary.setText(text);
        String description="Остаток квоты · "+String.join("; ",descriptions)+". Нажмите для подробностей";
        quotaSummary.setContentDescription(description);quotaSummary.setTooltipText(description);
    }
